  hx = `Manage %1$s Images`,
  gx = `Add a rich header image to your detail page to communicate the theme or essence of your update or announcement. Note that it is important to download the templates (link at the top of this page) to ensure that your header image is designed appropriately for the variety of circumstances in which it is used.`,
