  Tx = `Critical content should be placed within the center 940px of your image. The artwork can bleed out to the sides and down the page as desired. You generally want artwork to fade to a solid color on sides and bottom and then set the page background color to match. Please keep the image below 4MB.`,
  Ex = `Download All Sale Page Templates (.psd files)`,
