  Ax = `If provided, this banner will appear on the store page for all of the games that are part of this sale event. This banner lasts for the duration of the sales event, up to two weeks. Note that this banner must be approved by Valve prior to use and cannot be animated.`,
  jx = `This version only appears when the page resolution shrink for a mobile display.`,
  Mx = `You can also update your library hero image with branding for your update, announcement, season, or other event. To do so, please visit the "graphical assets" tab in the store page admin.`,
