  Fx = `Usage`,
  Ix = `Required`,
  Lx = `Optional`,
  Rx = `This image usually contains artwork and branding that represents your event, plus any brief message you want to call out. Steam will automatically include your game's name and icon next to this image in some contexts, but you may want to include your game logo in the cover image as well since this image is used when your event is shared on social media.`,
  zx = `It will appear on your store page in recent announcements, in lists of events and announcements, and on your library detail page. This image will be used to represent the event when it is shared on social media. It's used to link to your event/announcement and may be displayed alongside content from multiple games, so the image should be clear and recognizable.`,
  Bx = `This image usually contains artwork and branding that represents your publisher, developer, or franchise. Steam will automatically include your avatar icon next to this image in some contexts.`,
  Vx = `It will appear in places in Steam where this Creator Home is displayed and will be used to represent the event when it is shared on social media. The image should be clear and recognizable.`,
  Hx = `Banner image for Best of Year link on Steam Charts`,
