  YC = `By default, Steam will automatically pull any live Broadcast associated with any game that appears on this sales page. No action is required if the default makes sense for this sale. However, if you need to explicitly control which streams appear on the sale page, you can enable this flag and explicitly choose them in the broadcast tab.`,
