  nT = `This is a list of all the sale linked items that are currently not placed within ANY section, either explicitly or included through a filter. This is useful for making sure every element is visible on a sale and exploring groupings of unused items.`,
  rT = `Show Label Breakdown`,
  iT = `Hide Label Breakdown`,
  aT = `Linked items provide a pool of items along with associated attributes that can be added to the sale via filters that can select which items match based upon a defined criterion. It is important to note that these items aren't actually part of the sale or visible to users until they are included in either a tab or a sale section through a filter.`,
  oT = `This provides a listing of all the labels contained by the matching items and how many of each there are. This is useful for determining if there may be other breakdowns of labels available. Each label can be selected to see which items in the list have the associated label.`,
  sT = `No filter has been setup - Including all linked items`,
