  tL = `Items Per Row`,
  nL = `The number of items that will be shown in this section. Smaller numbers provide larger views while larger numbers will show more items at one time. Some allow different numbers per row, such as 2/3/4 shows two items on a row, then 3, then 4, and back down to 3, 2.`,
