  aR = `Dynamic Reveal Section`,
  oR = `A dynamic reveal section is useful in conjunction with a live announcement stream. It allows an operator to add store visible apps/packages/bundles after the sale is visible and have them appear in a Steam customers view of the page without requiring them to reload the page. We recommend that this section is placed near the broadcast player. Make sure to only add visible apps or the store page will cache their hidden state and the app won’t be visible to the Steam customers.`,
